<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowRight, CheckCircle2, FlaskConical, GitBranch, Info, LoaderCircle, Play } from 'lucide-vue-next'
import { api, isDemo } from '../api/client'
import type { Mode, QARequest, QAResponse } from '../api/types'
import { useWorkspace } from '../stores/workspace'
import { shortCommit, validateQA } from '../lib/presentation'
const store = useWorkspace(), question = ref('沙河雁南一站式多功能厅的预约平台还能办理哪些手续？'), running = ref(false), results = ref<{ mode: Mode; response: QAResponse; elapsed: number }[]>([]), error = ref('')
const comparable = computed(() => results.value.length === 2 && results.value[0].response.source_commit === results.value[1].response.source_commit && results.value[0].response.knowledge_revision === results.value[1].response.knowledge_revision)
async function compare() { if (store.syncing || store.qaPending || running.value) return; running.value = true; store.labRunning = true; error.value = ''; results.value = []; try { for (const mode of ['hybrid', 'vector'] as Mode[]) { const input: QARequest = { question: question.value.trim(), campus: 'shahe', mode, entity_bindings: {} }, start = performance.now(); const response = await api.qa(input), issues = validateQA(response); if (issues.length) throw new Error(issues.join('；')); results.value.push({ mode, response, elapsed: performance.now() - start }) } } catch (e) { error.value = e instanceof Error ? e.message : '对比请求失败' } finally { running.value = false; store.labRunning = false } }
</script>
<template>
  <div class="page lab-page"><div class="page-heading"><h1>检索对比</h1><p>比较同一问题的混合检索与向量检索结果。</p></div><div class="notice info"><Info :size="18" /><p>{{ isDemo ? '演示版使用内置样例，结果和耗时不代表真实检索表现。' : '两个请求依次执行。请由后端保证同模型、同上下文预算；界面仅检查来源快照一致性。' }}</p></div><div class="settings-card"><label class="form-label" for="compare-question">对比问题（沙河校区）</label><textarea id="compare-question" v-model="question" rows="2" :disabled="running" class="lab-question"></textarea><div class="lab-form-footer"><span class="helper">两个请求依次执行。</span><button class="button primary" :disabled="!question.trim() || running || store.syncing || store.qaPending" @click="compare"><component :is="running ? LoaderCircle : Play" :class="{ spinning: running }" :size="15" />{{ running ? '对比处理中…' : '开始对比' }}</button></div></div><div v-if="error" class="notice warning" role="alert"><p>{{ error }}</p></div><div v-if="results.length === 2" :class="['notice', comparable ? 'success' : 'warning']"><CheckCircle2 :size="17" /><p>{{ comparable ? '两份结果的来源版本一致。模型与上下文预算需由后端保证。' : '两次响应版本不一致，不能据此进行有效对比，请重新运行。' }}</p></div><div v-if="results.length" class="comparison-grid"><article v-for="result in results" :key="result.mode" class="comparison-card"><div class="card-heading"><div><GitBranch :size="17" /><h3>{{ result.mode === 'hybrid' ? '混合检索' : '仅向量检索' }}</h3></div><span class="pill blue mono">{{ result.mode.toUpperCase() }}</span></div><p v-for="(answer, i) in result.response.answers" :key="i" class="comparison-answer">{{ answer.text }}</p><p v-if="!result.response.answers.length" class="comparison-answer">{{ result.response.status }} · {{ result.response.reason || '无可展示结论' }}</p><dl><div><dt>来源版本</dt><dd class="mono">{{ shortCommit(result.response.source_commit) }}</dd></div><div><dt>支持路径</dt><dd>{{ result.response.paths.length }} 条</dd></div><div><dt>原文依据</dt><dd>{{ result.response.evidence.length }} 条</dd></div><div><dt>浏览器往返耗时</dt><dd class="mono">{{ (result.elapsed / 1000).toFixed(2) }} s</dd></div></dl><div class="comparison-evidence"><h4>支持材料</h4><button v-for="e in result.response.evidence" :key="e.id" @click="store.drawerEvidence = e">{{ e.heading }}<ArrowRight :size="14" /></button></div><p class="helper">{{ result.response.warnings.join(' ') }}</p></article></div></div>
</template>
